// Deterministic Natural Earth 50m Land Point Dataset
// Generated from 1,420 high-resolution geographic land polygons
// Total land points: 10645

export const TOTAL_LAND_DOTS = 10645;

// Base64 encoded Float32Array of (x, y, z) unit sphere coordinates
const LAND_POSITIONS_B64 = "";

let cachedPositions: Float32Array | null = null;

export function getLandPositions(): Float32Array {
  if (cachedPositions) return cachedPositions;
  const binaryString = atob(LAND_POSITIONS_B64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  cachedPositions = new Float32Array(bytes.buffer);
  return cachedPositions;
}

